SELECT *
FROM biz_park_pay
WHERE 1=1
AND pay_code = #{payCode}
AND wo_no = #{woNo}
AND reservation_id = #{reservationId}
AND pay_wo_no = #{payWoNo}
AND park_lot_id = #{parkLotId}
AND park_lot_name LIKE CONCAT('%', #{parkLotName}, '%')
AND berth_id = #{berthId}
AND berth_no = #{berthNo}
AND plate_num = #{plateNum}

    AND entry_time >= #{entryTime[0]}
    AND entry_time <= #{entryTime[1]}


    AND exit_time >= #{exitTime[0]}
    AND exit_time <= #{exitTime[1]}


    AND pay_time >= #{payTime[0]}
    AND pay_time <= #{payTime[1]}


    AND create_time >= #{createTime[0]}
    AND create_time <= #{createTime[1]}

AND create_time >= #{statStartTime}
AND create_time <= #{statEndTime}
AND region_full_code = #{regionFullCode}
AND region_name LIKE CONCAT('%', #{regionName}, '%')
AND grid_name LIKE CONCAT('%', #{gridName}, '%')
AND ext_cat1 = #{extCat1}
AND ext_cat2 = #{extCat2}
AND ext_common1 = #{extCommon1}
AND ext_common2 = #{extCommon2}
ORDER BY id DESC

